// The table below is the WHATWG Encoding Standard's 'index Big5', encoded as
// a base64 little-endian Uint32Array (one Unicode code point per Big5
// pointer, 0 for pointers the standard leaves unassigned).
// Refs: https://encoding.spec.whatwg.org/index-big5.txt
// Refs: https://encoding.spec.whatwg.org/#big5-decoder

'use strict';

const {
  StringFromCodePoint,
  Uint32Array,
} = primordials;

const { Buffer } = require('buffer');

const {
  ERR_ENCODING_INVALID_ENCODED_DATA,
} = require('internal/errors').codes;

/* eslint-disable @stylistic/js/max-len */
const kBig5TableBase64 =
  '';
/* eslint-enable @stylistic/js/max-len */

let big5Table;
function getBig5Table() {
  if (big5Table === undefined) {
    const buf = Buffer.from(kBig5TableBase64, 'base64');
    big5Table = new Uint32Array(buf.buffer, buf.byteOffset, buf.byteLength / 4);
  }
  return big5Table;
}

function isBig5Encoding(enc) {
  return enc === 'big5';
}

// Implements https://encoding.spec.whatwg.org/#big5-decoder
//
// Kept intentionally separate from the ICU-backed converter used for the
// other legacy multi-byte encodings: ICU's own Big5 conversion table
// includes vendor/PUA mappings the WHATWG Encoding Standard does not, so
// byte sequences the standard defines as invalid (and which must decode to
// U+FFFD) instead decode to those extra ICU-only characters. See
// https://github.com/nodejs/node/issues/61041 and
// https://github.com/nodejs/node/issues/40091.
function createBig5Decoder(fatal) {
  const table = getBig5Table();
  let lead = 0;

  function handleError() {
    if (fatal) {
      throw new ERR_ENCODING_INVALID_ENCODED_DATA('big5', undefined);
    }
    return '\uFFFD';
  }

  function run(bytes, flush) {
    let out = '';
    for (let i = 0; i < bytes.length; i++) {
      const byte = bytes[i];

      if (lead !== 0) {
        const leadByte = lead;
        lead = 0;

        let ptr = -1;
        if ((byte >= 0x40 && byte <= 0x7e) || (byte >= 0xa1 && byte <= 0xfe)) {
          const offset = byte < 0x7f ? 0x40 : 0x62;
          ptr = (leadByte - 0x81) * 157 + (byte - offset);
        }

        // A handful of Big5 pointers decode to two combining code points
        // rather than one; the standard special-cases them ahead of the
        // index table lookup.
        if (ptr === 1133) { out += '\u00CA\u0304'; continue; }
        if (ptr === 1135) { out += '\u00CA\u030C'; continue; }
        if (ptr === 1164) { out += '\u00EA\u0304'; continue; }
        if (ptr === 1166) { out += '\u00EA\u030C'; continue; }

        const cp = ptr === -1 ? 0 : table[ptr];
        if (cp === 0) {
          out += handleError();
          // If the byte that failed to complete the sequence is itself a
          // valid ASCII byte, the standard reprocesses it instead of
          // consuming it as part of the (invalid) Big5 sequence.
          if (byte < 0x80) i--;
          continue;
        }

        out += StringFromCodePoint(cp);
        continue;
      }

      if (byte < 0x80) {
        out += StringFromCodePoint(byte);
      } else if (byte >= 0x81 && byte <= 0xfe) {
        lead = byte;
      } else {
        out += handleError();
      }
    }

    if (flush && lead !== 0) {
      lead = 0;
      out += handleError();
    }

    return out;
  }

  return {
    write(buf) { return run(buf, false); },
    end(buf) { return run(buf, true); },
  };
}

module.exports = {
  isBig5Encoding,
  createBig5Decoder,
};
